const arr = (r: any, keys: string[]): any[] => {
  if (Array.isArray(r)) return r;
  if (typeof r === "string") { try { return arr(JSON.parse(r), keys); } catch { return []; } }
  for (const k of keys) if (r && Array.isArray(r[k])) return r[k];
  return [];
};
const login = (c: any): string | undefined =>
  c?.user?.login ?? c?.author?.login ?? c?.user ?? c?.author ?? c?.login;

const issues: any[] = [];
for (let page = 1; page <= 50; page++) {
  const r = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
  const items = arr(r, ["issues", "items", "data"]);
  if (items.length === 0) break;
  issues.push(...items);
  if (items.length < 50) break;
}

const perIssue: Record<string, number[]> = {};
const counts: Record<string, Set<number>> = {};
const issueNums: number[] = [];
for (const it of issues) {
  const n = it.number ?? it.iid;
  if (n === undefined) continue;
  if (it.labels && !JSON.stringify(it.labels).includes('"perf"')) continue;
  issueNums.push(n);
  const commenters = new Set<string>();
  for (let page = 1; page <= 50; page++) {
    const r = await tools.list_comments({ repo: "acme/web", number: n, page });
    const comments = arr(r, ["comments", "items", "data"]);
    if (comments.length === 0) break;
    for (const c of comments) {
      const l = login(c);
      if (l) commenters.add(l);
    }
    if (comments.length < 50) break;
  }
  for (const l of commenters) {
    (counts[l] ??= new Set()).add(n);
  }
}

const result = Object.entries(counts)
  .filter(([, s]) => s.size >= 4)
  .map(([l]) => l)
  .sort();

return { issueCount: issueNums.length, issueNums, result, all: Object.fromEntries(Object.entries(counts).map(([l, s]) => [l, [...s]])) };
